 $$('[data-ledger]').forEach(b=>b.onclick=()=>{const name=b.dataset.ledger,rows=[];for(const e of entries)for(const l of e.lines||[])if(l.account===name)rows.push({at:e.at,ref:e.ref,note:e.note,debit:num(l.debit),credit:num(l.credit)});let bal=0;rows.sort((a,b)=>new Date(a.at)-new Date(b.at)).forEach(r=>bal+=r.debit-r.credit);modal(`كشف حساب — ${name}`,`<div class="notice">الرصيد الحالي: ${money(bal)}</div><div class="table-wrap section-gap-sm"><table class="table compact"><thead><tr><th>التاريخ</th><th>المرجع</th><th>البيان</th><th>مدين</th><th>دائن</th></tr></thead><tbody>${rows.reverse().map(r=>`<tr><td>${A.fmtDT(r.at)}</td><td>${esc(r.ref)}</td><td>${esc(r.note)}</td><td>${money(r.debit)}</td><td>${money(r.credit)}</td></tr>`).join('')}</tbody></table></div>`,`<button class="btn" data-close>إغلاق</button>`);enhanceTables($('#modalRoot'))});
 $('#manualJournal').onclick=()=>{const opts=[...new Set([...names,'الخزينة','البنك','المخزون','المبيعات','تكلفة البضاعة المباعة','دائنون - موردون','عملاء','مصروفات تشغيلية'])].map(n=>`<option value="${esc(n)}"></option>`).join('');modal('قيد يدوي',`<datalist id="accNames">${opts}</datalist><form id="manualJournalForm" class="form-grid two"><label>الحساب المدين<input name="debitAccount" list="accNames" required></label><label>المبلغ المدين<input name="debit" type="number" min="0.01" step="0.01" required></label><label>الحساب الدائن<input name="creditAccount" list="accNames" required></label><label>المبلغ الدائن<input name="credit" type="number" min="0.01" step="0.01" required></label><label class="span-all">البيان<input name="note" required></label></form>`,`<button class="btn" data-close>إلغاء</button><button id="saveManualJournal" class="btn primary">ترحيل</button>`);$('#saveManualJournal').onclick=async()=>{if(window.PharmaRemote?.enabled&&!window.PharmaRemote.inAtomic())return window.PharmaRemote.atomic(()=>$('#saveManualJournal').onclick(),'sync');const f=$('#manualJournalForm');if(!f.reportValidity())return;const o=Object.fromEntries(new FormData(f));if(Math.abs(num(o.debit)-num(o.credit))>.01){toast('القيد غير متوازن','danger');return}const ref='MJ-'+Date.now();await A.journal(ref,'manual',[{account:o.debitAccount,debit:num(o.debit),credit:0},{account:o.creditAccount,debit:0,credit:num(o.credit)}],o.note);await audit('قيد يدوي',`${ref} • ${o.note}`);closeModal();toast('تم ترحيل القيد');A.render()}}
